class Solution {
public:
    int getMaximumGenerated(int n) {
        if (n == 0) return 0;
        vector<int> a(n + 1, 0);
        a[1] = 1;
        int best = 1;
        for (int i = 2; i <= n; i++) {
            a[i] = i % 2 == 0 ? a[i / 2] : a[i / 2] + a[i / 2 + 1];
            best = max(best, a[i]);
        }
        return best;
    }
};
